import kotlinx.coroutines.flow.*

data class Note(val titre: String)

interface DepotNotes {
    fun toutes(): List<Note>
}

class DepotMemoire : DepotNotes {
    override fun toutes() = listOf(Note("Kotlin"), Note("Gradle"))
}

class FauxDepotVide : DepotNotes {
    override fun toutes() = emptyList<Note>()
}

data class EtatNotes(val titres: List<String> = emptyList())

class NotesViewModel(private val depot: DepotNotes) {
    private val _etat = MutableStateFlow(EtatNotes())
    val etat: StateFlow<EtatNotes> = _etat

    fun actualiser() {
        _etat.value = EtatNotes(depot.toutes().map { it.titre })
    }
}

fun main() {
    val vm = NotesViewModel(DepotMemoire())
    vm.actualiser()
    println(vm.etat.value.titres)

    val test = NotesViewModel(FauxDepotVide())
    test.actualiser()
    println(test.etat.value.titres.isEmpty())
}
